// SERVER ONLY. Serve only after investor authentication.
const assets={
"architecture-model":{mime:"model/gltf-binary",data:""},
"architecture-overview":{mime:"image/png",data:""},
"architecture-manufacturing":{mime:"image/png",data:""},
};
export function architectureAsset(action,method){if(method!=="GET"||!Object.hasOwn(assets,action))return null;const a=assets[action];return {bytes:Buffer.from(a.data,"base64"),mime:a.mime};}
